/* ÇEVİRİ it · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("it","olay",{
"OLAYLAR_P0057:1793-01-31:0":{"b": ["La Contea di Nizza è annessa alla Francia", "a140cab2"], "d": ["Dopo l'annessione della Savoia nel novembre 1792, la Convenzione Nazionale francese il 31 gennaio 1793 sancì l'annessione alla Francia della Contea di Nizza, appartenente al Regno di Sardegna; la regione divenne il dipartimento delle Alpi Marittime. Nizza tornò alla Sardegna con il primo Trattato di Parigi del 30 maggio 1814, dopo la sconfitta di Napoleone.", "b313c90b"]},
"OLAYLAR_P0057:1917-01-09:0":{"b": ["Scontro di Rafah — la cavalleria anglo-anzac prende le posizioni di Magrunteyn e Rafah", "5053c8ef"], "d": ["La Divisione Montata Anzac, la Brigata del Corpo Cammellato Imperiale e una brigata di yeomanry britannica della Forza Expeditionary Egiziana, attraversato il Sinai, attaccarono a Magrunteyn, circa un chilometro a sud di Rafah, la posizione ottomana tenuta con ridotte. Dopo un duro scontro lo sfondamento dei Neozelandesi e delle unità cammellate fece crollare la difesa ottomana; la posizione e la vicina Rafah furono prese e le forze britanniche raggiunsero il confine palestinese.", "7f90289f"]},
"OLAYLAR_P0057:1918-03-12:0":{"b": ["L'offensiva invernale di Kâzım Karabekir: con Erzurum è ripresa Hasankale (Pasinler)", "27df4879"], "d": ["Le forze ottomane al comando di Kâzım Karabekir Pascià, passate all'operazione in oriente dopo la disgregazione dell'esercito russo, nonostante le gravi condizioni invernali ripresero Erzincan, Erzurum e Hasankale, a est di Erzurum; l'avanzata si estese a Kars il 25 aprile 1918.", "80a72c73"]},
"OLAYLAR_P0057:1919-01-23:0":{"b": ["L'occupazione britannica di Eskişehir", "8e349037"], "d": ["Dopo l'Armistizio di Mudros, le potenze dell'Intesa cominciarono a porre sotto controllo i nodi ferroviari dell'Anatolia. Secondo la voce Eskişehir del TDV, la città fu occupata dagli Inglesi il 23 gennaio 1919. Le truppe britanniche evacuarono Eskişehir il 20 marzo 1920.", "5bb8774d"]},
"OLAYLAR_P0057:1919-05-11:0":{"b": ["Lo sbarco degli Italiani sulle coste dell'Anatolia sud-occidentale — Marmaris, Bodrum, Kuşadası", "15d6fb7a"], "d": ["L'Italia, che aveva lasciato la Conferenza di Pace di Parigi per protesta contro l'atteggiamento filo-greco degli alleati, dopo Antalya sbarcò truppe sulle coste sud-occidentali. Secondo il TDV, il 5 maggio Marmaris, l'11 maggio Bodrum, il 13 maggio Kuşadası subirono l'occupazione italiana. Negli stessi giorni anche i Greci sbarcarono a Fethiye; la rivalità tra i due Stati sull'Anatolia occidentale preparò la via all'occupazione di Smirne.", "82266143"]},
"OLAYLAR_P0057:1919-05-26:0":{"b": ["L'ingresso delle forze greche a Manisa e Aydın", "a4230775"], "d": ["L'esercito greco, sbarcato a Smirne il 15 maggio, si estese in breve alle zone interne. Secondo la voce Manisa del TDV, le forze greche entrarono in città il 26 maggio 1919; secondo la voce Aydın, Aydın fu occupata il giorno seguente, il 27 maggio. L'occupazione di Manisa sarebbe durata fino al settembre 1922.", "514ead8b"]},
"OLAYLAR_P0057:1919-06-28:0":{"b": ["L'occupazione italiana di Burdur — il ritiro della compagnia diretta a Isparta", "874e9d6d"], "d": ["Gli Italiani, che avevano occupato Antalya, avanzarono verso le regioni interne. Secondo la voce Isparta del TDV, le truppe italiane occuparono Burdur il 28 giugno e il 15 agosto si diressero a Isparta con una compagnia di soldati. Poiché la popolazione di Isparta rifiutò la proposta di consegnare le armi e fece sapere che avrebbe resistito, gli Italiani si ritirarono il giorno seguente.", "35806188"]},
"OLAYLAR_P0057:1919-06-30:0":{"b": ["La breve liberazione di Aydın e la nuova occupazione del 4 luglio", "753c739f"], "d": ["Contro l'occupazione greca si organizzarono forze nazionali nei dintorni di Ödemiş, Nazilli e Aydın. Secondo la voce Aydın del TDV, la città, occupata il 27 maggio 1919, fu liberata per breve tempo il 30 giugno, ma il 4 luglio subì di nuovo l'occupazione greca. La città rimase poi sotto occupazione fino al 7 settembre 1922.", "a0031b01"]},
"OLAYLAR_P0057:1919-07-23:0":{"b": ["L'occupazione italiana di Muğla", "a4f5a926"], "d": ["L'Italia estese l'occupazione delle coste sud-occidentali alle zone interne. Secondo la voce Muğla del TDV, la città subì l'occupazione italiana il 23 luglio 1919. L'occupazione di Muğla durò fino al 5 luglio 1921.", "b77c243c"]},
"OLAYLAR_P0057:1919-10-15:0":{"b": ["Inizio dell'amministrazione militare francese in Tracia occidentale", "5801e6de"], "d": ["La Tracia occidentale, in mano alla Bulgaria che aveva perso la prima guerra mondiale, fu posta sotto il controllo delle potenze dell'Intesa mentre proseguivano i colloqui di pace. Secondo la voce Batı Trakya del TDV, la regione fu occupata il 15 ottobre 1919 dalle forze francesi; la Società per la Difesa dei Diritti della Tracia Occidentale in questo periodo spostò la sua sede a Komotini (Gümülcine). L'amministrazione francese durò fino alla cessione della regione alla Grecia nel maggio 1920 con la decisione di Sanremo.", "58f44e3a"]},
"OLAYLAR_P0057:1920-03-20:0":{"b": ["Gli Inglesi evacuano Eskişehir", "6820e164"], "d": ["Eskişehir, sotto occupazione britannica dal gennaio 1919, fu evacuata dagli Inglesi il 20 marzo 1920, secondo la voce Eskişehir del TDV. Pochi mesi dopo, nel giugno 1920, la città divenne il centro del Fronte Occidentale costituito dalla Grande Assemblea Nazionale.", "5f817d34"]},
"OLAYLAR_P0057:1920-06-22:0":{"b": ["L'offensiva estiva greca — occupazione di Akhisar, Soma, Balıkesir e Alaşehir", "f096d2b4"], "d": ["Con il permesso concesso dagli Alleati all'esercito greco di superare la linea Milne e avanzare, iniziò nell'Anatolia occidentale una grande offensiva greca. Secondo la voce Millî Mücadele del TDV, le unità greche, mosse il 22 giugno in tre colonne, presero Akhisar, Kırkağaç, Soma e Balıkesir. A sud il 26 giugno fu occupata Alaşehir e il 3 luglio Nazilli.", "bb4b4b94"]},
"OLAYLAR_P0057:1920-07-08:0":{"b": ["L'occupazione greca di Bursa", "7c2b32a1"], "d": ["Il ramo settentrionale dell'offensiva estiva, dopo Balıkesir, si volse verso il Marmara. Secondo le voci Bursa e Millî Mücadele del TDV, Bursa subì l'occupazione greca l'8 luglio 1920. Le profanazioni delle tombe dei primi sovrani ottomani suscitarono una grande reazione in tutto il paese.", "2f040dcd"]},
"OLAYLAR_P0057:1920-07-20:0":{"b": ["L'occupazione della Tracia orientale da parte dell'esercito greco — Edirne e Kırklareli", "9eb3bda1"], "d": ["La Grecia, prima che fosse firmato il Trattato di Sèvres, tentò di impadronirsi di fatto anche della Tracia orientale. Secondo la voce Millî Mücadele del TDV, l'esercito greco il 20 luglio prese tutta la Tracia; questo sviluppo spinse a Istanbul il sultano a convocare due giorni dopo il Consiglio del Sultanato. Kırklareli subì l'occupazione il 26 luglio ed Edirne entrò sotto amministrazione greca nello stesso mese.", "4c68dd1f"]},
"OLAYLAR_P0057:1920-07-28:0":{"b": ["L'ingresso dell'Armata Rossa a Nakhichevan", "6dcb9005"], "d": ["Gli Inglesi, entrati nella regione all'inizio del 1919, avevano sciolto la Repubblica dell'Aras e nell'estate dello stesso anno avevano lasciato Nakhichevan. Secondo la voce Nahçıvan del TDV, l'Armata Rossa il 28 luglio 1920 entrò a Nakhichevan, affidò l'amministrazione ai comunisti e fu costituita la Repubblica Socialista Sovietica di Nakhichevan. Lo status della regione fu fissato nel 1921, con il trattato firmato a Kars, come unità autonoma legata all'Azerbaigian.", "bc49ebba"]},
"OLAYLAR_P0057:1920-08-29:0":{"b": ["L'occupazione greca di Uşak", "74ad2713"], "d": ["L'esercito greco proseguì l'avanzata allo scopo di far accettare il Trattato di Sèvres, non riconosciuto da Ankara. Secondo le voci Uşak e Millî Mücadele del TDV, dopo Gediz fu occupata anche Uşak il 29 agosto 1920. Mustafa Kemal Pascià aveva ispezionato le unità delle Kuvâ-yi Milliye nella città circa un mese prima di questa occupazione.", "b7c70a40"]},
"OLAYLAR_P0057:1920-10-25:0":{"b": ["L'occupazione greca di İnegöl e Yenişehir", "4a0460e7"], "d": ["Le truppe greche a Bursa cominciarono ad avanzare verso est, in direzione di Eskişehir. Secondo la voce Millî Mücadele del TDV, il 25 ottobre 1920 furono prese İnegöl e Yenişehir. Quando si comprese che l'avanzata greca non poteva essere fermata con le forze di milizia, il fronte occidentale fu riorganizzato su base di esercito regolare.", "53e977e3"]},
"OLAYLAR_P0057:1921-01-01:0":{"b": ["Fine dell'occupazione italiana di Burdur (anno)", "609123c8"], "d": ["Burdur, occupata dagli Italiani il 28 giugno 1919, secondo la voce Burdur del TDV conobbe una breve occupazione italiana tra il 1919 e il 1921. La fonte non dà il giorno dello sgombero; sulla mappa l'occupazione termina all'inizio dell'anno 1921. L'Italia si ritirò del tutto dalla zona di occupazione in Anatolia nell'estate del 1921.", "0ac33ff9"]},
"OLAYLAR_P0057:1921-03-23:0":{"b": ["La seconda offensiva dell'esercito greco — occupazione di Bilecik, Afyon e Adapazarı", "9ae146e2"], "d": ["L'esercito greco, che dopo la sconfitta della prima battaglia di İnönü aveva fatto sbarcare a Smirne nuove forze, passò di nuovo all'offensiva prima che scadesse il termine riconosciuto dalla Conferenza di Londra. Secondo la voce Millî Mücadele del TDV, i Greci il 23 marzo occuparono Bilecik e Afyon. A nord anche Adapazarı subì l'occupazione greca il 25 marzo.", "7d247e77"]},
"OLAYLAR_P0057:1921-03-28:0":{"b": ["Le forze turche evacuano Batum", "ba5745dc"], "d": ["Gli Inglesi, ritirandosi dal Caucaso nel luglio 1920, avevano evacuato Batum e la città era stata presa dal governo georgiano. Secondo la voce Batum del TDV, il Trattato di Mosca firmato il 16 marzo 1921 con la Russia sovietica lasciò Batum alla Georgia. Le forze turche evacuarono la città il 28 marzo 1921 e Batum divenne il centro della Repubblica Autonoma di Agiaria costituita in Georgia.", "9555d8e0"]},
"OLAYLAR_P0057:1921-04-07:0":{"b": ["La ripresa di Afyon — battaglie di Aslıhanlar", "2bbba17b"], "d": ["Dopo l'offensiva greca fermata il 1° aprile a İnönü II, sul fronte meridionale Afyon fu ripresa il 7 aprile. La voce Millî Mücadele del TDV lo riassume come 'Aslıhanlar’da ağır yenilgiye uğratılarak 7 Nisan’da Afyon geri alındı'; tuttavia gli studi di storia militare collocano gli scontri di Aslıhanlar-Dumlupınar dopo l'evacuazione di Afyon, tra l'8 e il 15 aprile, e scrivono che la superiorità tattica rimase dalla parte greca — le due narrazioni non coincidono, sono date entrambe. La vittoria di İnönü fu celebrata con comizi in tutto il paese, a cominciare da Istanbul.", "3525b97a"]},
"OLAYLAR_P0057:1921-06-28:0":{"b": ["La liberazione di İzmit — dopo Adapazarı", "cec60e36"], "d": ["Adapazarı, che nel marzo 1921 aveva subito l'occupazione greca, fu ripresa il 21 giugno secondo la voce Adapazarı del TDV. Secondo la voce İzmit del TDV, anche İzmit, occupata il 6 luglio 1920 prima dagli Inglesi e poi dai Greci, fu liberata il 28 giugno 1921. I Greci, lasciando la città, incendiarono la zona del bazar.", "da5f0806"]},
"OLAYLAR_P0057:1921-07-05:0":{"b": ["La liberazione di Muğla dall'occupazione italiana", "143ddf98"], "d": ["L'Italia cominciò a ritirarsi dalla zona di occupazione in Anatolia nell'estate del 1921; l'evacuazione di Antalya era iniziata il 1° giugno. Secondo la voce Muğla del TDV, Muğla, sotto occupazione italiana dal 23 luglio 1919, fu liberata il 5 luglio 1921.", "84bff82f"]},
"OLAYLAR_P0057:1921-07-20:0":{"b": ["L'evacuazione di Eskişehir — l'esercito greco entra a Eskişehir, Kütahya e Bilecik", "a948a74d"], "d": ["L'esercito turco, colto impreparato nelle battaglie di Kütahya-Eskişehir, per ordine di Mustafa Kemal Pascià si ritirò a est del Sakarya. Secondo le voci del TDV, i Greci entrarono il 20 luglio 1921 a Eskişehir, il 21 luglio a Kütahya, il 22 luglio a Bilecik. Il re greco Costantino il 28 luglio presiedette a Kütahya un consiglio di guerra e l'esercito si preparò ad attaccare in direzione di Ankara.", "29f7f871"]},
"OLAYLAR_P0057:1922-04-29:0":{"b": ["Ritiro delle truppe italiane da Marmaris e Kuşadası", "1d672994"], "d": ["Gli Italiani, presenti dal maggio 1919 sulle coste dell'Anatolia sud-occidentale, dopo il riavvicinamento con il Governo di Ankara sgomberarono la zona di occupazione passo dopo passo. Antalya e Bodrum erano state evacuate nell'estate del 1921; le ultime truppe italiane lasciarono anche Kuşadası e Marmaris alla fine dell'aprile 1922.", "f956076c"]},
"OLAYLAR_P0057:1922-08-26:0":{"b": ["Inizia la Grande Offensiva", "efba4bd3"], "d": ["Dopo un anno di preparativi seguito a Sakarya, l'esercito turco passò all'offensiva generale sul fronte di Afyon. Secondo le voci Millî Mücadele e Kütahya del TDV, la Grande Offensiva iniziò da Afyon la mattina del 26 agosto 1922 e la resistenza dell'esercito greco fu presto spezzata.", "7eaf426f"]},
"OLAYLAR_P0057:1922-08-27:0":{"b": ["La liberazione di Afyon", "beaeef23"], "d": ["Il secondo giorno dell'offensiva il fronte greco fu sfondato davanti ad Afyon. Secondo la voce Afyonkarahisar del TDV, al termine della Grande Offensiva, comandata personalmente da Atatürk, le forze greche furono sbaragliate e la città fu liberata il 27 agosto 1922. Questo giorno è celebrato come giorno della liberazione di Afyon.", "bfb4dd98"]},
"OLAYLAR_P0057:1922-08-30:0":{"b": ["La Battaglia del Comandante in Capo — liberazione di Kütahya", "376d3118"], "d": ["Le forze principali dell'esercito greco furono accerchiate tra Afyon e Dumlupınar. Secondo la voce Millî Mücadele del TDV, l'operazione di accerchiamento fu completata il 30 agosto con la Battaglia del Comandante in Capo, diretta personalmente dal comandante in capo Mustafa Kemal Pascià. Secondo la voce Kütahya del TDV, lo stesso giorno una divisione di cavalleria liberò Kütahya, incendiata e distrutta dalle forze greche in ritirata.", "6ecd76e4"]},
"OLAYLAR_P0057:1922-09-01:0":{"b": ["La liberazione di Uşak", "0f2d44d1"], "d": ["Dopo la Battaglia del Comandante in Capo i resti dell'esercito greco si ritirarono a ovest, in direzione di Smirne. Secondo la voce Uşak del TDV, Uşak, sotto occupazione dal 29 agosto 1920, fu liberata il 1° settembre 1922 con l'ingresso delle forze nazionali in città. Nell'incendio provocato dalle forze di occupazione in ritirata bruciò circa tre quarti della città.", "ea4dc034"]},
"OLAYLAR_P0057:1922-09-02:0":{"b": ["La liberazione di Eskişehir", "f442de5c"], "d": ["Sul fianco settentrionale della Grande Offensiva le forze greche dovettero abbandonare anche Eskişehir. Secondo la voce Eskişehir del TDV, la città, sotto occupazione dal 20 luglio 1921, fu liberata il 2 settembre 1922 dopo la vittoria del 30 agosto. Al termine di tredici mesi di occupazione la zona del bazar era stata incendiata e la città era distrutta per metà.", "3b15a7c5"]},
"OLAYLAR_P0057:1922-09-06:0":{"b": ["La liberazione di Bilecik", "35dbd49b"], "d": ["Secondo la voce Bilecik del TDV, la città subì tre volte l'occupazione greca durante la Lotta Nazionale; la terza occupazione, iniziata il 22 luglio 1921, ebbe fine il 6 settembre 1922. Nell'incendio provocato dalle forze greche nel lasciare la città bruciò gran parte delle case, delle botteghe e del palazzo del governo.", "28e74c34"]},
"OLAYLAR_P0057:1922-09-07:0":{"b": ["La liberazione di Aydın", "ef1280b5"], "d": ["Con l'avvicinarsi dell'esercito turco a Smirne si ritirarono anche le forze greche nella valle del Meandro. Secondo la voce Aydın del TDV, la città fu liberata dalle forze turche il 7 settembre 1922, in parte distrutta e con la popolazione molto diminuita. I Greci in ritirata avevano incendiato gran parte della città.", "358e3333"]},
"OLAYLAR_P0057:1922-09-11:0":{"b": ["La ripresa di Bursa", "6ad1da0b"], "d": ["Dopo la liberazione di Smirne l'esercito turco avanzò a nord verso le coste del Marmara. Secondo la voce Bursa del TDV, la città, sotto occupazione greca dall'8 luglio 1920, fu ripresa il 10-11 settembre 1922. La marcia dell'esercito di qui verso Çanakkale allarmò gli Inglesi e aprì la strada ai colloqui di Mudanya.", "caa09d48"]},
"OLAYLAR_P0057:1922-11-10:0":{"b": ["La presa in consegna della Tracia orientale — Kırklareli e Tekirdağ", "2a08d65c"], "d": ["L'Armistizio di Mudanya prevedeva l'evacuazione della Tracia orientale da parte dell'esercito greco e la sua consegna alla Turchia; Refet Pascià, incaricato di prendere in consegna la Tracia, giunse a Istanbul il 19 ottobre. Secondo il TDV, Kırklareli, sotto occupazione dal 26 luglio 1920, fu ripresa il 10 novembre 1922 e anche Tekirdağ fu restituita ai Turchi il 13 novembre in base all'armistizio. Così la Tracia orientale fu annessa ai territori turchi senza combattere.", "cb085872"]},
"OLAYLAR_P0058:1339-01-01:0":{"b": ["Eretna annette alle sue terre le regioni di Tokat, Kayseri e Samsun", "4a088f9f"], "d": ["L'emiro Eretna, rafforzatosi in Anatolia come governatore ilkhanide, dopo aver riguadagnato l'appoggio del sultano mamelucco al-Nāṣir Muḥammad, nel 1339 ampliò i suoi confini e annesse alle sue terre le regioni di Tokat, Kayseri e Samsun. In questo periodo entrò sotto l'amministrazione di Eretna anche la regione di Zamantı, a est di Kayseri. Il beylik proclamò l'indipendenza nel 1341 con la morte di al-Nāṣir.", "5be963a4"]},
"OLAYLAR_P0058:1360-01-01:0":{"b": ["Halil Bey dei Dulkadiridi estende i suoi confini fino a Zamantı", "aa911e87"], "d": ["Con la salita al comando del Beylik di Eretna del piccolo Mehmed Bey, le incursioni turcomanne da sud contro le terre indebolite di Eretna aumentarono. Nel 1360, mentre il capo turcomanno Ömer Bey prendeva Malatya, Halil Bey Dulkadıroğlu estese i confini del suo beylik fino a Zamantı, a est di Kayseri. Così la regione di Zamantı, tra Elbistan e Kayseri, passò ai Dulkadiridi e il beylik la tenne fino all'annessione ottomana del 1515.", "6f54371d"]},
"OLAYLAR_P0058:1394-01-01:0":{"b": ["Bayezid il Fulmine pone di nuovo Istanbul sotto uno stretto assedio", "244834ca"], "d": ["Costantinopoli, tenuta a intermittenza sotto blocco dal 1391, nella primavera del 1394 fu posta di nuovo sotto stretto assedio da Bayezid il Fulmine. Il rapporto con Bisanzio, che dal 1371 pagava tributo agli Ottomani e inviava aiuti militari, si trasformò così in aperta ostilità. L'assedio fu tolto con il profilarsi del pericolo di Tamerlano e con la battaglia di Ankara del 1402.", "c3af0f1d"]},
"OLAYLAR_P0058:1424-02-22:0":{"b": ["Pace bizantina con Murad II — Bisanzio accetta di nuovo di pagare il tributo", "6474d704"], "d": ["Murad II, che nel 1422 aveva assediato Costantinopoli contro Bisanzio, sostenitrice del falso Mustafa, il 22 febbraio 1424 firmò un trattato di pace con l'imperatore bizantino. Con questo trattato Bisanzio accettò di pagare di nuovo il tributo agli Ottomani e di restituire i luoghi presi dopo il 1402 sulle coste del Marmara, dell'Egeo e del Mar Nero, eccetto le fortezze di Selymbria (Silivri) e Terkos; il tributo annuo da cui si era liberata con l'accordo del 1403 con l'emiro Süleyman tornò così. Bisanzio mantenne questa condizione fino alla conquista di Costantinopoli nel 1453.", "dd19c749"]},
"OLAYLAR_P0058:1514-10-23:0":{"b": ["Le fortezze di Bayburt e Kiğı sono consegnate dai Safavidi — Erzincan e Bayburt date a Bıyıklı Mehmed Bey", "2c7fd65e"], "d": ["Dopo la vittoria di Çaldıran, mentre Selim il Severo, di ritorno da Tabriz, era nel suo accampamento, giunsero le notizie della presa in consegna delle fortezze di Bayburt e Kiğı. Il sancakbey di Trebisonda Bıyıklı Mehmed Bey e il sancakbey di Giannina Mustafa Bey presero nell'ottobre 1514 Bayburt, difesa da Kara Maksûd-i Sultânî, uno degli emiri di Shah Ismail. Erzincan, entrata senza combattere sotto il dominio ottomano, fu data insieme a Bayburt il 23 ottobre 1514 come beylerbeylik a Bıyıklı Mehmed Bey e Bayburt divenne sede di sanjak.", "d3796513"]},
"OLAYLAR_P0058:1514-11-24:0":{"b": ["Selim il Severo torna dalla campagna di Tabriz ad Amasya e vi trascorre l'inverno", "49d51f94"], "d": ["Selim il Severo, rimasto nove giorni a Tabriz, rinunciò a trascorrere l'inverno in Persia per le difficoltà di approvvigionamento e la riluttanza dei soldati, e tornò passando per Kars e Bayburt. Celebrata a Niksar la Festa della fine del Ramadan, il sultano giunse ad Amasya e vi trascorse l'inverno. Aveva l'intenzione di marciare di nuovo contro i Safavidi l'anno seguente; ad Amasya iniziò la pressione dei giannizzeri per tornare a Istanbul e la campagna proseguì nella primavera del 1515 con la conquista di Kemah.", "2693e398"]},
"OLAYLAR_P0059:1594-11-13:0":{"b": ["Valacchia, Moldavia e Transilvania si ribellano insieme agli Ottomani", "e71d3ee9"], "d": ["A metà del 1594 i tre voivodati a nord del Danubio — Valacchia, Moldavia e Transilvania — decisero un'azione comune contro gli Ottomani. Il voivoda di Moldavia Aron Tiran aderì alla Lega Santa costituita dall'imperatore d'Austria e da papa Clemente VIII e si sottomise al Principato di Transilvania; il voivoda di Valacchia Mihai Viteazul si unì al movimento per il malcontento verso il peso delle tasse. Il 13 novembre 1594 in Valacchia e Moldavia iniziarono rivolte simultanee contro il dominio ottomano e, con l'appoggio della Transilvania, il movimento si riversò a sud del Danubio, verso i territori ottomani. Secondo l'Enciclopedia dell'Islam del TDV, questa alleanza a tre aprì il fronte settentrionale della Lunga Guerra ottomano-asburgica (1593-1606), in corso negli stessi anni.", "30f44add"]},
"OLAYLAR_P0069:1523-01-01:0":{"b": ["Conquista della fortezza di Ostrovica nella valle dell'Una", "5c6cc91b"], "d": ["Ostrovica, in mano ai Frangipane e ad altri nobili croati, sorgeva su un'erta cresta che collegava le parti settentrionale e meridionale della valle dell'Una. Passò all'amministrazione ottomana nel 1523 e ospitò una guarnigione ottomana fino al 1878. La fortezza acquistò la sua vera importanza dopo Carlowitz (1699): per la vicinanza al confine veneziano e austriaco fu ampliata e divenne centro del capitanato di Stara Ostrovica; la cittadina di Kulen Vakuf fu fondata ai suoi piedi all'inizio del XVIII secolo.", "0978b370"]},
"OLAYLAR_P0069:1527-05-01:0":{"b": ["Conquista delle fortezze di Udbina e Krbava — la Lika entra sotto amministrazione ottomana", "5fe329d3"], "d": ["La piana di Krbava era stata svuotata nel 1524 e a Udbina restava solo la guarnigione di Karlović. Karlović riportò nell'aprile 1527 un'ultima vittoria davanti alla fortezza, ma alla fine di maggio Udbina, insieme alle fortezze di Mrsinj e Komić, cadde nelle mani del pascià di Bosnia. Nello stesso anno la zona di Gospić fu data agli agha Senković. La Lika e la Krbava divennero poi parte del sanjak con centro a Obrovac, che nel 1580 prese il nome di Kırka.", "0e759e1a"]},
"OLAYLAR_P0069:1592-01-01:0":{"b": ["Il passaggio definitivo di Drežnik e della contea (županija) di Drežnik all'amministrazione ottomana", "6624ad14"], "d": ["Drežnik, in mano ai Frangipane dal 1323, era stata tenuta temporaneamente dagli Ottomani nel 1578. Nel 1592 la fortezza e l'intera županija di Drežnik entrarono definitivamente sotto l'amministrazione ottomana; nello stesso anno cadde anche Bihać. Nel XVIII secolo Drežnik dipendeva dal capitanato di Ostrožac.", "b41efb59"]},
"OLAYLAR_P0069:1636-01-01:0":{"b": ["La presa della fortezza di Cetin da parte degli Ottomani", "98815f97"], "d": ["Cetin, fortezza chiave nella difesa della regione di Slunj contro gli Ottomani dalla metà del XVI secolo, dopo ripetuti assedi passò nel 1636 sotto l'amministrazione ottomana. Questo primo periodo ottomano durò due anni.", "44a52e6e"]},
"OLAYLAR_P0069:1638-01-01:0":{"b": ["Il ritorno della fortezza di Cetin dalla parte asburgica", "690f9f84"], "d": ["Cetin, passata in mano ottomana nel 1636, nel 1638 tornò alla difesa di frontiera croato-asburgica e vi rimase fino al 1670.", "8f16b3ec"]},
"OLAYLAR_P0069:1670-01-01:0":{"b": ["Cetin torna fortezza ottomana", "e1750675"], "d": ["Cetin nel 1670 tornò a essere fortezza ottomana e nel XVIII secolo fu fortificata in modo sostanziale: la fortezza medievale fu cinta da mura con bastioni. La fortezza tenne fino al 1790 l'estremità nord-occidentale della frontiera di Bosnia.", "3cf8713d"]},
"OLAYLAR_P0069:1689-01-01:0":{"b": ["La perdita di Lika e Krbava — Udbina e Gospić passano alle forze di frontiera asburgiche", "01277a38"], "d": ["Nella guerra proseguita dopo la disfatta di Vienna, le truppe di frontiera croate al comando di Herberstein, generale di Karlovac, presero Udbina nel 1689; nello stesso anno anche Gospić uscì dall'amministrazione ottomana. La Lika ottomana, durata oltre 160 anni, ebbe fine, i luoghi svuotati furono ripopolati con nuova popolazione croata e Udbina divenne, fino alla pace di Sistova (1791), un'importante fortezza della difesa di frontiera contro gli Ottomani.", "bde1a0dc"]},
"OLAYLAR_P0069:1788-01-01:0":{"b": ["La presa di Drežnik da parte austriaca — fronte occidentale della battaglia di Dubica", "05d5e5f1"], "d": ["Nella guerra ottomano-austriaca del 1788-1791 le forze asburgiche presero Drežnik, a ovest di Bihać. Con l'articolo 4 del Trattato di Sistova Drežnik e Cetin rimasero sotto amministrazione asburgica e non tornarono più alla Bosnia.", "30f8f200"]},
"OLAYLAR_P0069:1790-01-01:0":{"b": ["La presa della fortezza di Cetin da parte austriaca", "df182480"], "d": ["Nel 1790 l'esercito asburgico attaccò Cetin, Bužim e Velika Kladuša e prese Cetin. La mobilitazione proclamata dal governatore di Bosnia e il contrattacco non riuscirono a riprendere la fortezza; l'articolo 4 del Trattato di Sistova lasciò Cetin agli Asburgo. I difensori di frontiera bosniaci la ripresero con brevi incursioni nel 1809 e nel 1813.", "fc69baec"]},
"OLAYLAR_SEHIR_ILK:1284-03-20:0":{"b": ["Bilecik è citata per la prima volta — il confine con Bisanzio iniziava a Bilecik", "7b69f743"], "d": ["Negli avvenimenti dell'anno 683 riportati da Neşrî, Bilecik compare come il luogo da cui inizia il confine tra il beylik di frontiera di Osman Bey e Bisanzio. È la prima menzione storica nota dell'insediamento; non è la sua fondazione.", "f668b296"]},
"OLAYLAR_SEHIR_ILK:1299-09-28:0":{"b": ["A Burdur moneta a nome di Ghazan Khan — la prima attestazione nota della città", "01974ddc"], "d": ["Gli Hamidoğulları, sotto la pressione ilkhanide, furono costretti nell'anno 699 a far coniare a Burdur moneta a nome di Ghazan Khan. Questa moneta è la prima attestazione scritta/datata di Burdur.", "83a1e1ee"]},
"OLAYLAR_SEHIR_ILK:1352-03-01:0":{"b": ["Çorum è citata nel paese di Eretna — la prima attestazione nota della città", "bf7bd67f"], "d": ["Alla morte di Eretna Bey, nel Muharram 753, Çorum è annoverata tra le città sotto il suo dominio. La fondazione della città è ignota; questa menzione è l'attestazione datata più antica reperibile.", "68c8fd3f"]},
"OLAYLAR_SEHIR_ILK:1368-01-20:0":{"b": ["Brăila è citata per la prima volta — privilegio di Vlaicu Vodă ai mercanti di Brașov", "0b3517a7"], "d": ["Il voivoda di Valacchia Vladislav concesse ai mercanti di Brașov un documento che dava facilitazioni nel trasporto di merci lungo la via di Brăila. Questo documento è la prima attestazione scritta nota di Brăila; il luogo vi compare non ancora come città, ma come estremità della strada sul Danubio. Non è la data di fondazione.", "8ed7db79"]},
"OLAYLAR_SEHIR_ILK:1420-01-01:0":{"b": ["Chişinău è citata per la prima volta in un decreto del voivoda di Moldavia", "a50799d7"], "d": ["Il nome di Chişinău compare per la prima volta in un decreto del voivoda di Moldavia Alexandru del 1420. La città rimase a lungo una piccola cittadina moldava; passata nel 1812 alla Russia insieme alla Bessarabia, divenne capoluogo di provincia.", "61d831d5"]},
"OLAYLAR_SEHIR_ILK:1445-01-01:0":{"b": ["Galați è citata per la prima volta in un documento di un voivoda di Moldavia", "a31af8a2"], "d": ["Il voivoda di Moldavia Ștefan II esentò dalla tassa doganale due carri del Monastero di Humor che portavano pesce da Galați. Questo documento è la prima attestazione scritta sicuramente nota di Galați; l'insediamento può essere esistito prima come villaggio di pescatori sulla riva del Danubio.", "40d464f1"]},
"OLAYLAR_SEHIR_ILK:1452-04-03:0":{"b": ["Il nome di Mostar compare per la prima volta in un documento di Ragusa", "a599bc55"], "d": ["Il nome di Mostar compare per la prima volta in un documento di Ragusa (Dubrovnik) del 3 aprile 1452; l'insediamento si trovava nei territori del Ducato di Erzegovina. La conquista ottomana è del 1466-68.", "5fba613f"]},
"OLAYLAR_SEHIR_ILK:1458-01-01:0":{"b": ["A Sarajevo la Moschea dell'Imperatore (Hünkâr) — la più antica attestazione datata dell'insediamento", "ad697a7d"], "d": ["Il sancakbey di Bosnia İshak Bey, nel primo insediamento musulmano nella piana di Saray, fece costruire per sé un palazzo, a nome di Maometto il Conquistatore la Moschea dell'Imperatore (Hünkâr) e accanto un bagno. La moschea è datata 862 (1458); è la più antica costruzione datata nota di Sarajevo.", "d7927c3d"]},
"OLAYLAR_SEHIR_ILK:1462-02-01:0":{"b": ["Atto di fondazione (vakfiye) di İshak Bey — il nucleo cittadino di Sarajevo è dotato in waqf", "0b364229"], "d": ["Dal vakfiye di İshak Bey datato Cemaziyelevvel 866 (febbraio 1462) si comprende che, oltre alla moschea e al bagno, furono costruiti una zâviye, una mevlevîhâne, un imaret, un ponte sulla Miljacka, sulla riva opposta il Kolobara Han, il bedesten, un caravanserraglio e botteghe. Il documento è il fondamento waqf della città; l'insediamento esisteva già prima.", "5f20e8f0"]},
"OLAYLAR_SEHIR_ILK:1472-06-08:0":{"b": ["Tatarpazarcığı (Pazardžik) è registrata per la prima volta in un registro degli akıncı", "3b1c839e"], "d": ["I registri più antichi sulla città risalgono all'anno 877 (1472): un registro di akıncı conservato nella Biblioteca Nazionale di Sofia registra l'insediamento.", "45a744f9"]},
"OLAYLAR_SEHIR_ILK:1494-02-06:0":{"b": ["Banja Luka è citata per la prima volta in un'istruzione del re Vladislao II", "0ebc6288"], "d": ["Il nome di Banja Luka compare per la prima volta in un'istruzione del re ungaro-croato Vladislao II del 6 febbraio 1494; la zona dipendeva dalla corona ungherese tramite il banato di Jajce. La conquista ottomana è dell'inverno 1527-28.", "02da21ca"]},
"OLAYLAR_SEHIR_ILK:1494-10-02:0":{"b": ["La popolazione di Bassora completa il trasferimento nel sito attuale — l'antica Bassora è abbandonata", "20f96eac"], "d": ["La popolazione, trovando l'odierna Bassora più sicura contro gli attacchi beduini e potendovi procurarsi più comodamente l'acqua, aveva cominciato col tempo a stabilirvisi; il passaggio al nuovo sito si completò nell'anno 900 (1494-95). L'antica Bassora, fondata ai tempi di 'Umar, si trovava a circa 25 km dalla città attuale.", "7e2ce96c"]},
"OLAYLAR_SEHIR_ILK:1503-01-01:0":{"b": ["Mengli Giray Khan fa costruire il Palazzo del Khan sul Çürüksu — fondamenta di Bakhchysarai", "0792497c"], "d": ["Nella valle, zona di caccia e di riposo estivo dei governatori dell'Orda d'Oro e dei primi khan di Crimea, Mengli Giray Khan I fece costruire sulle rive del Çürüksu il palazzo oggi noto come Palazzo del Khan, ponendo le fondamenta di Bakhchysarai. La città si sviluppò attorno al palazzo e lungo la stretta valle del Çürüksu e verso la fine del XVI secolo divenne fiorente e centro del Khanato di Crimea.", "dbbc246c"]},
"OLAYLAR_SEHIR_ILK:1552-01-01:0":{"b": ["I Cosacchi Zaporoghi fondano la prima Sič sull'isola di Chortycja", "e6ca0dd9"], "d": ["Il principe Dmytro Vyšnevec'kyj fondò la prima Sič Zaporoga sull'isola di Mala Chortycja nel Dnepr. La fortezza fu assediata e distrutta dai Tatari di Crimea nel 1558; la Sič fu poi spostata sulle isole più a sud. Termine: «Sič» (ucraino Sich) è il campo-centro dei Cosacchi Zaporoghi sulle isole del Dnepr, fortificato con tronchi e fossati; è quartier generale, sede dell'assemblea (Rada) e del capo eletto dell'esercito (koševyj), non capitale di Stato.", "2af408f9"]},
"OLAYLAR_SEHIR_ILK:1593-01-01:0":{"b": ["Fondata la Sič di Bazavluk", "fcd507ae"], "d": ["Dopo che i Tatari ebbero distrutto la Sič di Tomakivka, i Cosacchi Zaporoghi fondarono una nuova Sič sull'isola di Bazavluk, alla confluenza del Dnepr con i suoi rami Čortomlyk, Pidpilna e Skarbna. La Sič fu distrutta nel 1638 con la campagna polacca successiva alla repressione della rivolta cosacca. Termine: «Sič» (ucraino Sich) è il campo-centro dei Cosacchi Zaporoghi sulle isole del Dnepr, fortificato con tronchi e fossati; è quartier generale, sede dell'assemblea (Rada) e del capo eletto dell'esercito (koševyj), non capitale di Stato. In questa data l'«Etmanato» non esiste ancora (1648); il nome Zaporož'e significa «oltre le rapide» e le Sič stanno sul confine di steppa a valle delle rapide del Dnepr. Non ha parentela etnica con i Cosacchi del Kazakistan: i Cosacchi Zaporoghi sono una comunità slava orientale (ucraina) e ortodossa; in comune hanno solo la parola «cosacco» (guerriero libero), di origine turca.", "ecc27d31"]},
"OLAYLAR_SEHIR_ILK:1628-01-01:0":{"b": ["La Sič di Mykytyn Rih è citata per la prima volta", "61e22abc"], "d": ["Il nome della quarta Sič, fondata a Mykytyn Rih nel luogo dell'odierna Nikopol', compare per la prima volta nel 1628; fu presa nel 1648 da Bohdan Chmel'nyc'kyj. È la prima attestazione nota del luogo, non la sua fondazione.", "63f059d0"]},
"OLAYLAR_SEHIR_ILK:1652-01-01:0":{"b": ["Fondata la Sič di Čortomlyk", "4b6e8197"], "d": ["I Cosacchi Zaporoghi fondarono sul promontorio alla confluenza del Dnepr con il fiume Čortomlyk la Sič di Čortomlyk, detta anche 'Vecchia Sič'. La Sič fu distrutta il 25 maggio 1709 dall'esercito russo perché aveva sostenuto Mazepa.", "e7b8c2ca"]},
"OLAYLAR_SEHIR_ILK:1654-01-01:0":{"b": ["Char'kov è fondata da emigrati cosacchi", "288b303c"], "d": ["Sul margine settentrionale della selvaggia steppa, alla confluenza dei fiumi Lopan' e Char'kov, emigrati cosacchi giunti dalla riva destra del Dnepr fondarono un insediamento. Char'kov divenne presto il centro della Sloboda Ucraina, legata a Mosca.", "0d185061"]},
"OLAYLAR_SEHIR_ILK:1711-01-01:0":{"b": ["I Cosacchi Zaporoghi fondano con il permesso del khan di Crimea la Sič di Aleški", "ed26f29d"], "d": ["Quando l'offensiva russa fece sgomberare la Sič di Kamjanka, i Cosacchi Zaporoghi, con il permesso del khan di Crimea, si stabilirono ad Aleški, sulla riva sinistra del fiume Konka, in territorio del khanato. Dopo il Trattato del Prut si unirono a loro anche i Cosacchi di Hordijenko. Il khan non permise alla Sič di avere mura e cannoni.", "acb5924a"]},
"OLAYLAR_SEHIR_ILK:1728-01-01:0":{"b": ["La Sič di Aleški è saccheggiata e abbandonata", "52361709"], "d": ["I Cosacchi di Samara, filorussi, assalirono e saccheggiarono la Sič di Aleški e incendiarono gli alloggiamenti. La Sič non fu ricostruita; i Cosacchi nel 1730 tornarono a Kamjanka e nel 1734, prestato giuramento di fedeltà alla Russia, fondarono la Nuova Sič.", "bf03f792"]},
"OLAYLAR_SEHIR_ILK:1738-01-01:0":{"b": ["Fondata sul Volga la fortezza di Stavropol'", "eb087a50"], "d": ["Sul medio Volga fu fondata la fortezza di Stavropol' per i Calmucchi convertiti al cristianesimo (l'odierna Togliatti).", "d486bb18"]},
"OLAYLAR_SEHIR_ILK:1738-03-24:0":{"b": ["Nadir Shah prende Kandahar e ne fa distruggere la vecchia città", "9cc23e6b"], "d": ["Il sovrano afsharide Nadir Shah prese, dopo un lungo assedio, Kandahar, in mano agli Afghani Ghilzai. La città fu distrutta e la sua popolazione si trasferì a Naderabad, fondata a sud-est del vecchio sito; la vecchia Kandahar non fu più una città.", "c8df437b"]},
"OLAYLAR_SEHIR_ILK:1777-01-01:0":{"b": ["Fondata la fortezza di Stavropol' sulla linea Azov-Mozdok", "7fd9b9f1"], "d": ["Dopo Küçük Kaynarca, sulla linea fortificata Azov-Mozdok, fondata per controllare la steppa tra il Kuban' e il Terek, furono costruite dieci fortezze; una era Stavropol'. La fortezza divenne poi il centro del governatorato del Caucaso e del governatorato di Stavropol'.", "f27157a3"]},
"OLAYLAR_SEHIR_ILK:1778-01-01:0":{"b": ["Fondato il cantiere navale di Cherson alla foce del Dnepr", "115f2c34"], "d": ["Alla foce del Dnepr, passata alla Russia dopo Küçük Kaynarca, vicino alla fortificazione Aleksandr-šanc, costruita nel 1737 e subito distrutta, fu fondato un cantiere navale e fu dato il nome di Cherson. La città divenne capoluogo di distretto nel 1784 e di governatorato nel 1803.", "a664a96e"]},
"OLAYLAR_SEHIR_ILK:1779-01-01:0":{"b": ["I Greci venuti dalla Crimea fondano Mariupol' sulla costa d'Azov", "4e3af209"], "d": ["I Greci venuti dalla Crimea fondarono Mariupol' dove il Kal'mius sfocia nel Mar d'Azov. La città divenne nel 1784 capoluogo di distretto dipendente dal governatorato di Ekaterinoslav.", "d36ebbc5"]},
"OLAYLAR_SEHIR_ILK:1783-01-01:0":{"b": ["Ekaterinoslav è spostata nel sito attuale sulla riva del Dnepr", "ec361381"], "d": ["Ekaterinoslav, fondata da Potëmkin nel 1778 alla confluenza dei fiumi Kil'čen' e Samara, fu trasferita nel 1783 nel sito attuale a causa della posizione insalubre.", "b37ccddb"]},
"OLAYLAR_SEHIR_ILK:1784-01-01:0":{"b": ["Fondato nella baia di Achtiar il porto della flotta russa, Sebastopoli", "01058a25"], "d": ["Dopo l'annessione della Crimea alla Russia nel 1783 fu scelta come porto militare la baia in cui si trovava il villaggio tataro di Crimea di Achtiar (Akyar); il porto fu fondato l'anno seguente e prese il nome di Sebastopoli. La città divenne nel 1804 il porto principale della flotta russa del Mar Nero.", "03079154"]},
"OLAYLAR_SEHIR_ILK:1784-01-01:1":{"b": ["Fondata la fortificazione di Nikolaev alla foce del Bug", "d57e52b9"], "d": ["Alla confluenza dei fiumi Bug Meridionale e Ingul fu fondata una fortificazione per ordine del principe Potëmkin. Nel 1788 vi fu aperto un cantiere navale e l'insediamento divenne uno dei centri di costruzione navale della flotta del Mar Nero.", "76edde36"]},
"OLAYLAR_SEHIR_ILK:1784-01-01:2":{"b": ["Fondato sul Moločna l'insediamento di frontiera nucleo di Melitopol'", "637d5817"], "d": ["Dopo l'annessione della Crimea fu fondato sulle rive del fiume Moločna un insediamento di frontiera. L'insediamento nel 1816 prese il nome di Novooleksandrivka e nel 1841 fu fatto città con il nome di Melitopol'.", "9151422f"]},
"OLAYLAR_SEHIR_ILK:1805-01-01:0":{"b": ["Fondata Novočerkassk, nuovo centro dell'Armata Cosacca del Don", "bf5709fd"], "d": ["Il centro amministrativo dell'Armata Cosacca del Don passò da Čerkassk, che fino ad allora era stata il centro, a Novočerkassk, fondata nella località di Birjučij Kut tra i fiumi Aksaj e Tuzlov.", "544a425d"]},
"OLAYLAR_SEHIR_ILK:1813-03-06:0":{"b": ["Wadi Halfa è registrata nel viaggio in Nubia di Burckhardt", "6efc72ec"], "d": ["Il viaggiatore svizzero J. L. Burckhardt scrive nel suo diario del 6 marzo 1813 di essere passato per Wadi Halfa e che vi si faceva un certo commercio. È la prima attestazione datata reperibile.", "a3a1877c"]},
"OLAYLAR_SEHIR_ILK:1827-01-01:0":{"b": ["Fondato sulla costa d'Azov l'approdo di Berdjansk", "908ac3cf"], "d": ["Per iniziativa del principe Michail Voroncov fu fondata Berdjansk dove il fiume Berda sfocia nel Mar d'Azov. L'insediamento divenne città nel 1835 e capoluogo di distretto nel 1842.", "8742949e"]},
"OLAYLAR_SEHIR_ILK:1838-01-01:0":{"b": ["La popolazione di Malatya resta nei giardini di Aspuzu — nucleo dell'odierna Malatya", "d1dba159"], "d": ["Nell'estate del 1838 il quartier generale ottomano contro l'esercito egiziano di Ibrahim Pascià si spostò da Mezraa a Malatya. I Malatyani, che abitavano nelle case estive di Aspuzu, dopo la partenza dell'esercito non tornarono alle case invernali della vecchia città, rimasta in rovina; Aspuzu divenne il nucleo dell'odierna Malatya. La vecchia Malatya (Battalgazi) continuò a vivere ridotta.", "f4d616ac"]},
"OLAYLAR_SEHIR_ILK:1918-04-02:0":{"b": ["Van è fondata nel nuovo sito — la vecchia città in rovina è abbandonata", "6d278578"], "d": ["Van fu liberata dall'occupazione il 2 aprile 1918. Coloro che tornarono, invece di riparare la vecchia Van sulla riva del lago, distrutta negli anni di guerra, fondarono una nuova città a circa 7 km all'interno dalla riva, nel luogo degli antichi quartieri di Norşen e Arak. La vecchia città fu abbandonata.", "5a729844"]},
"OLAYLAR_SENKRON_0930:1298-01-01:0":{"b": ["Maraş passa ai Mamelucchi — il naib di Aleppo Bilbân et-Tabahî la riprende agli Armeni", "03171265"], "d": ["Maraş, in mano al Regno armeno di Cilicia dal 1258, nel 1293 era passata per breve tempo ai Mamelucchi con l'accordo del sultano Halil con gli Armeni e, dopo il loro ritiro, era tornata in mano armena. Nel 697 (1298) il naib mamelucco di Aleppo, Bilbân et-Tabahî, riprese la città. Da allora Maraş rimase territorio mamelucco fino all'ascesa dei Dulkadiridi.", "8fd31b13"]},
"OLAYLAR_SENKRON_0930:1372-01-01:0":{"b": ["L'Impero bizantino diventa tributario degli Ottomani", "615df998"], "d": ["Dopo la vittoria di Çirmen (Maritza, 1371), l'imperatore bizantino Giovanni V accettò nell'inverno del 1372 di diventare tributario di Murad I: avrebbe pagato un tributo annuo e fornito soldati alle campagne del sultano. Da allora fino al 1403 Bisanzio rimase uno Stato vassallo degli Ottomani; il blocco di Bayezid il Fulmine del 1391 aumentò il tributo. Dopo il disastro di Ankara, l'accordo di Gallipoli (1403) con Süleyman Çelebi liberò Bisanzio dal tributo; nel 1424, con l'accordo con Murad II, il tributo riprese.", "e3c816ac"]},
"OLAYLAR_SENKRON_0930:1399-09-01:0":{"b": ["Bayezid il Fulmine, dopo la morte di Barquq, annette Behisni, Darende e Divriği ai domini ottomani", "8e57d7e6"], "d": ["Dopo la morte del sultano mamelucco Barquq (giugno 1399), quando gli affari amministrativi dello Stato mamelucco entrarono in crisi, Bayezid il Fulmine scese nel bacino dell'Eufrate e annesse ai domini ottomani, insieme a Malatya, Behisni (Besni), Darende e Divriği. Sivas era stata lasciata agli Ottomani poco prima, dopo la morte di Kadı Burhâneddin nell'estate del 1398. Divriği era sotto dominio mamelucco dal 1391 ed era un avamposto dipendente dalla provincia di Aleppo. Il dominio ottomano non vi durò a lungo: per il pericolo incombente di Tamerlano, Divriği fu restituita ai Mamelucchi nel 1401, e la città entrò definitivamente sotto amministrazione ottomana solo dopo Marj Dabiq nel 1516.", "ec7cd171"]},
"OLAYLAR_SENKRON_0930:1400-08-01:0":{"b": ["Behisni passa ai Mamelucchi durante la campagna di Tamerlano contro Sivas e Malatya", "4853da9a"], "d": ["Behisni, presa da Bayezid il Fulmine nel 1398 insieme a Sivas, Darende e Malatya, passò ai Mamelucchi nel 1400, mentre Tamerlano prendeva Sivas e Malatya. Tamerlano conquistò anche Behisni il 27 settembre 1400 dopo un duro assedio; quando si ritirò dalla regione, Behisni rientrò sotto il dominio mamelucco e vi rimase (salvo una fase intermedia dulgadiride) finché Selim il Severo non la prese nell'agosto 1516.", "0ead96f9"]},
"OLAYLAR_SENKRON_0930:1401-01-01:0":{"b": ["Divriği restituita ai Mamelucchi per il pericolo di Tamerlano", "97196b1f"], "d": ["Divriği, presa ai Mamelucchi da Bayezid il Fulmine nel 1398, fu lasciata di nuovo ai Mamelucchi nel 1401 all'avvicinarsi di Tamerlano all'Anatolia. Per questo, dopo la distruzione di Sivas da parte di Tamerlano (1400), Divriği compare sulla mappa nel colore mamelucco; negli stessi mesi Bayezid prendeva a oriente Erzincan e Kemah, cosicché il territorio mamelucco restò incuneato tra i possedimenti ottomani a occidente (Sivas) e a nord-est (Kemah). Divriği passò definitivamente agli Ottomani solo dopo Marj Dabiq nel 1516.", "3f13d015"]},
"OLAYLAR_SENKRON_0930:1414-01-01:0":{"b": ["Il sultano mamelucco Şeyh riprende ai Dulkadiridi Antep e Darende", "f90c9508"], "d": ["Preoccupato dall'amicizia dei Dulkadiridi con gli Ottomani, il sultano mamelucco Şeyh intraprese una campagna nel 1414 e riprese Antep e Darende, che in precedenza aveva ceduto spontaneamente ai Dulkadiridi.", "9f9b94e1"]},
"OLAYLAR_SENKRON_0930:1418-01-01:0":{"b": ["Mehmed Bey Dulkadıroğlu riprende Darende e annette anche Behisni", "df914dcb"], "d": ["Mehmed Bey Dulkadıroğlu riprese nel 1418 Darende, presa dai Mamelucchi nel 1414, e annetté ai suoi territori anche Behisni.", "d469f850"]},
"OLAYLAR_SENKRON_0930:1436-01-01:0":{"b": ["I Mamelucchi sconfiggono i Dulkadiridi ad Antep; Behisni torna all'amministrazione mamelucca (approssimativo)", "72742430"], "d": ["L'esercito mamelucco sconfisse i Dulkadiridi ad Antep nel 1436 e Mehmed Bey si ritirò sull'Akdağ. L'anno del ritorno di Behisni ai Mamelucchi non è indicato nella fonte; Behisni era stata annessa ai Dulkadiridi nel 1418 ed era tornata ai Mamelucchi prima che Şehsuvar Bey la prendesse loro nel 1465. L'atlante restituisce Behisni ai Mamelucchi in coincidenza con questa sconfitta nel vicino centro di Antep (approssimazione dichiarata).", "dc3b71ff"]},
"OLAYLAR_SENKRON_0930:1467-01-01:0":{"b": ["Şehsuvar Bey Dulkadıroğlu prende Behisni ai Mamelucchi (approssimativo)", "843f0fc4"], "d": ["Şehsuvar Bey (1465-1472), nominato bey dei Dulkadiridi da Maometto il Conquistatore, conquistò Behisni, Gerger, Birecik e Rumkale, in mano ai Mamelucchi; i Mamelucchi furono sconfitti nell'autunno del 1467 al Turnadağı e nella primavera del 1468 presso Antep.", "c812ae2a"]},
"OLAYLAR_SENKRON_0930:1471-01-01:0":{"b": ["L'emiro Yeşbek sconfigge Şehsuvar Bey; Behisni torna all'amministrazione mamelucca (approssimativo)", "4d856aee"], "d": ["Nella primavera del 1471 l'emiro Yeşbek sconfisse Şehsuvar Bey sul torrente Savron; i Mamelucchi ripresero Kadirli e Kozan. Şehsuvar fu giustiziato al Cairo nel 1472 e i Mamelucchi reinsediarono Şahbudak come bey. Con questo ritorno anche Behisni entrò sotto l'amministrazione mamelucca (TDV besni: 'XV. yüzyılın sonlarına doğru yeniden Memlükler’in eline geçti').", "3ba3c319"]},
"OLAYLAR_SENKRON_0930:1550-09-15:0":{"b": ["Le forze di Ferdinando occupano e fortificano Szolnok", "6c8416e6"], "d": ["Mentre gli Ottomani si preparavano a costruire una fortezza a Szolnok sul Tibisco, le forze di Ferdinando I li anticiparono: a metà settembre 1550 occuparono Szolnok e la fortezza fu resa difendibile a metà ottobre. Così Szolnok, appartenente al paese di Isabella, passò in mano asburgica un anno prima del passaggio della Transilvania a Ferdinando; gli Ottomani presero la fortezza nel 1552.", "eea8389b"]},
"OLAYLAR_SENKRON_0930:1551-07-26:0":{"b": ["La Transilvania passa all'amministrazione asburgica: l'assemblea di Kolozsvár riconosce la rinuncia di Isabella", "8458a566"], "d": ["In seguito all'accordo di Martinuzzi con Ferdinando, la regina Isabella, a nome del piccolo re János Zsigmond, firmò il 19 giugno 1551 nel castello di Szászsebes l'atto di rinuncia impostole. Il 26 luglio l'assemblea transilvana riunita a Kolozsvár riconobbe questa rinuncia e la sovranità di re Ferdinando; l'esercito asburgico del generale Castaldo entrò a Belgrado di Transilvania (Gyulafehérvár). Così la Transilvania, vassalla degli Ottomani, passò a un'amministrazione asburgica destinata a durare cinque anni.", "d8d0aad9"]},
"OLAYLAR_SENKRON_0930:1556-03-12:0":{"b": ["L'amministrazione asburgica in Transilvania ha fine: la Transilvania torna voivodato vassallo degli Ottomani", "721a482a"], "d": ["Gli Asburgo tentarono nel 1551 di impadronirsi della Transilvania tramite il prete di origine croata Martinuzzi (Fráter György), nominato tutore di János Zsigmond a causa della sua minore età; Belgrado di Transilvania (Gyulafehérvár), Kolozsvár, Brassó e Segesvár rimasero cinque anni sotto amministrazione asburgica. Gli Ottomani impedirono questa situazione e la Transilvania tornò a essere un voivodato tributario a loro soggetto. Da allora la Transilvania, nei secoli XVI e XVII, per circa 150 anni conservò uno statuto fondato su un'ampia autonomia negli affari interni e sulla soggezione a Istanbul in quelli esteri.", "0566dd84"]},
"OLAYLAR_SENKRON_0930:1557-01-01:0":{"b": ["Várad, Huszt e Tokaj passano dalla parte dei Szapolyai", "587c782d"], "d": ["Dopo il ritorno di Isabella e János Zsigmond in Transilvania nel 1556, i sostenitori dei Szapolyai assediarono Nagyvárad nel 1556. Nel 1557 gli aristocratici dell'Alto Tibisco presero le più importanti fortezze regie — Várad, Huszt e Tokaj; a Ferdinando restarono solo Gyula e Világos. Da allora Várad divenne la fortezza del principato di Transilvania e tale rimase finché gli Ottomani non la presero nel 1660.", "3f850e28"]},
"OLAYLAR_SENKRON_0930:1565-02-01:0":{"b": ["Schwendi prende Szatmár — l'estremità settentrionale della Transilvania passa agli Asburgo", "2256bb27"], "d": ["Szatmár, passata agli Asburgo nel 1561 con il cambio di campo di Balassa Menyhért, era stata ripresa per sorpresa da István Báthory nell'autunno del 1564 e annessa alla Transilvania. Il comandante asburgico Lazarus von Schwendi passò al contrattacco nel febbraio 1565: Tokaj cadde il 9 febbraio, Szerencs quattro giorni dopo, e Szatmár passò quasi senza resistenza nelle mani delle forze imperiali.", "8735c789"]},
"OLAYLAR_SENKRON_0930:1605-01-21:0":{"b": ["Le forze di Bocskai prendono Szatmár", "e93b098b"], "d": ["Mentre la rivolta di Bocskai si estendeva all'Ungheria nord-orientale, Gyulaffy, che la assediava, prese Szatmár il 21 gennaio 1605. La pace di Vienna del 23 giugno 1606 lasciò a Bocskai la contea di Szatmár a vita; poiché non vi erano eredi maschi, con la morte di Bocskai il 29 dicembre 1606 la contea tornò al regno.", "a7cde19a"]},
"OLAYLAR_SENKRON_0930:1606-12-29:0":{"b": ["Morte di István Bocskai — la contea di Szatmár torna al regno", "3721bb9b"], "d": ["Il principe di Transilvania István Bocskai morì a Kassa il 29 dicembre 1606. La pace di Vienna (23 giugno 1606) gli aveva lasciato a vita le contee, tra cui Szatmár, con ritorno al regno in assenza di eredi maschi; in forza di questa clausola la contea di Szatmár passò di nuovo al regno ungherese asburgico. La Transilvania si mise alla ricerca di un nuovo principe.", "bbe08ca4"]},
"OLAYLAR_SENKRON_0930:1619-11-01:0":{"b": ["Gábor Bethlen assume il controllo della contea di Szatmár", "80263da1"], "d": ["Con la campagna d'Ungheria di Gábor Bethlen nell'autunno del 1619, la contea di Szatmár passò sotto il controllo del principe di Transilvania; nel novembre 1619 egli si rivolgeva alla contea per lettera. Il preliminare del 23 gennaio 1620 e la pace di Nikolsburg lasciarono a Bethlen a vita sette contee, compresa Szatmár. Dopo la morte di Bethlen (15 novembre 1629), la restituzione delle contee al regno fu completata il 30 marzo 1630.", "76c6a30b"]},
"OLAYLAR_SENKRON_0930:1630-03-30:0":{"b": ["Completata la restituzione al regno delle sette contee di Gábor Bethlen", "31b5968f"], "d": ["La pace di Nikolsburg aveva lasciato a Gábor Bethlen a vita sette contee dell'Alta Ungheria, compresa Szatmár. Dopo la morte di Bethlen il 15 novembre 1629, la restituzione delle contee al regno iniziò con l'istruzione del 30 novembre 1629 e fu completata il 30 marzo 1630.", "dd97dafd"]},
"OLAYLAR_SENKRON_0930:1644-02-01:0":{"b": ["György I Rákóczi prende in consegna Szatmár", "f398635b"], "d": ["Nella campagna del 1644 del principe di Transilvania György I Rákóczi, la guarnigione tedesca di Szatmár passò al servizio di Rákóczi e la fortezza cadde in mano transilvana. La pace di Linz del 16 dicembre 1645 lasciò la fortezza agli eredi dei Rákóczi finché un Rákóczi fosse stato sul trono di Transilvania.", "17240548"]},
"OLAYLAR_SENKRON_0930:1664-05-03:0":{"b": ["La perdita di Nitra — De Souches riprende la fortezza", "c71bf012"], "d": ["Nitra, che dopo la conquista di Uyvar (Érsekújvár) nel 1663 si era arresa dopo breve resistenza, fu assediata il 15 aprile 1664 dal comandante imperiale De Souches; la fortezza si arrese il 3 maggio 1664. Poiché il trattato di Vasvár lasciava i luoghi conquistati nello stato in cui si trovavano, Uyvar restò agli Ottomani mentre Nitra restò in mano asburgica.", "b1d01f51"]},
"OLAYLAR_SENKRON_0930:1664-06-14:0":{"b": ["La perdita di Léva", "f311920e"], "d": ["Dopo Nitra, De Souches assediò Léva il 9 giugno 1664; il 13 giugno fu firmata la capitolazione e il 14 giugno la fortezza era in mano alle forze imperiali. La battaglia di Léva (Garamszentbenedek) del 19 luglio 1664 non cambiò il possesso; si concluse con la conservazione di Léva e Nitra da parte asburgica.", "7fe0a206"]},
"OLAYLAR_SENKRON_0930:1676-09-19:0":{"b": ["Dorošenko consegna Čyhyryn a Samojlovyč", "3b538237"], "d": ["L'etmano della riva destra sotto protezione ottomana, Petro Dorošenko, consegnò la capitale Čyhyryn il 19 settembre 1676 all'etmano della riva sinistra Samojlovyč e alle forze russe. Gli Ottomani destituirono Dorošenko e misero al suo posto Jurij Chmel'nyc'kyj; l'assedio del 1677 per espellere la guarnigione russa da Čyhyryn fallì, e la fortezza fu presa solo il 21 agosto 1678.", "cccf7b79"]},
"OLAYLAR_SENUSI_0919:1551-07-01:0":{"b": ["Consegna delle fortezze del Banato di Transilvania (Timișoara, Lipova, Lugoj, Karánsebes) al re d'Ungheria Ferdinando", "0e354976"], "d": ["Nel 1551 l'esercito asburgico al comando del generale Castaldo entrò in Transilvania; la regina Isabella e il figlio furono costretti a rinunciare ai loro diritti sul trono d'Ungheria. Con il consenso di Castaldo, Martinuzzi inviò a metà luglio 1551 Endre Báthory a prendere in consegna a nome di Ferdinando le fortezze di Timișoara, Lipova, Șoimoș, Karánsebes, Lugoj, Becse, Becskerek e Cenad. Le fortezze meridionali della Transilvania, posta sotto protezione ottomana, passarono così in mano asburgica; le campagne del Legislatore del 1551-1552 ne sono la risposta.", "420ca62a"]},
"OLAYLAR_SENUSI_0919:1554-04-07:0":{"b": ["Nomina di Petrovics Péter a sancakbey di Lugoj e Karánsebes", "bcbe73e4"], "d": ["Su insistente richiesta di Isabella e di Petrovics, il Legislatore decise di far tornare in Transilvania il piccolo János Zsigmond. Con una lettera scritta da Aleppo il 7 aprile 1554 ordinò ai Transilvani di ricondurre il bambino nel suo paese; ordinò inoltre ai voivodi di Valacchia e Moldavia di aiutare in questa impresa Petrovics, che nello stesso tempo nominò sancakbey di Lugoj e Karánsebes. Lugoj, conquistata nel 1552, fu così data a Petrovics come sanjak ottomano.", "6c5be465"]},
"OLAYLAR_SENUSI_0919:1596-05-10:0":{"b": ["La revoca dell'assedio di Lipova — il colpo del bano di Lugoj su Timișoara", "be03430e"], "d": ["Nella primavera del 1596 il pascià di Timișoara assediò Lipova. Nella notte tra il 10 e l'11 maggio, per ordine del bano di Lugoj della Transilvania, György Palatics, i soldati di György Buday assalirono e incendiarono i sobborghi di Timișoara; il fatto che György Borbély facesse sparare tutti i cannoni della fortezza fece credere al pascià che fossero giunti soccorsi. L'11 maggio il pascià si ritirò da Lipova per correre a difendere il proprio centro. Lugoj era in quel momento in mano al Principato di Transilvania.", "07e2cb97"]},
"OLAYLAR_SENUSI_0919:1688-01-01:0":{"b": ["L'occupazione di Orșova da parte delle forze austriache al comando di Veterani", "1b4a4f6c"], "d": ["Nella campagna del 1688 il generale Veterani, dopo aver preso Karánsebes, marciò su Orșova e occupò anche questa. La fonte non indica il giorno dell'occupazione; è usato il 1° gennaio 1688, base dell'anno.", "1dfe042e"]},
"OLAYLAR_SENUSI_0919:1689-07-15:0":{"b": ["La ripresa di Orșova da parte di Thököly e delle forze ottomane", "c5645da9"], "d": ["Dopo la presa di Vetislan, Thököly e i pascià ottomani marciarono su Orșova, occupata da Veterani nel 1688. Dopo scontri di poco conto, Thököly entrò a Orșova il 15 luglio 1689. Heissler, accorso alla notizia del pericolo, vedendo che la forza avversaria era ben fornita di munizioni e navi si ritirò per difendere la Transilvania. Anche l'attacco di Herbeville davanti alla città in agosto non riuscì a riprendere Orșova.", "6d469bdd"]},
"OLAYLAR_SENUSI_0919:1691-01-01:0":{"b": ["Il sanjak di Lugoj entra sotto occupazione asburgica (1691-1695)", "c8bcd6bd"], "d": ["Il sanjak di Lugoj rimase sotto occupazione asburgica (tedesca) tra il 1691 e il 1695; Mustafa II lo riconquistò il 22 settembre 1695. Nel vecchio registro il periodo 1689-1695 era un vuoto dichiarato; la fascia 1691-1695 è ora colorata come asburgica, il vuoto resta per il 1689-1691. La data è presa solo come anno.", "053d32c8"]},
"OLAYLAR_SENUSI_0919:1716-10-18:0":{"b": ["La fortezza di Lugoj entra sotto amministrazione asburgica", "6a9d401f"], "d": ["Lugoj, fortezza sede di sanjak dipendente dall'eyalet di Timișoara, era in mano ottomana dal 1695; con la resa del centro dell'eyalet al termine dell'assedio del 1716 fu lasciata alla Monarchia asburgica. Il vecchio registro poneva il passaggio al 1° gennaio 1716, base dell'anno.", "ab78a026"]},
"OLAYLAR_SENUSI_0919:1717-01-01:0":{"b": ["La presa di Orșova da parte dell'esercito asburgico (campagna del 1717)", "7a4faffe"], "d": ["Nella campagna del 1717 il generale Splényi giunse davanti a Orșova il 27 agosto e prese facilmente la città; Orșova, che Mercy non era riuscito a prendere nel 1716, passò così in mano asburgica. Poiché i favi della riva del Danubio circostante (compreso il tratto di Đerdap sulla sponda serba) dipendono dal punto abitato più vicino, Orșova, sono colorati con il suo proprietario. La data è presa solo come anno; il giorno preciso non è confermato.", "724e03d5"]},
"OLAYLAR_SENUSI_0919:1738-05-08:0":{"b": ["Il passaggio della palanca di Orșova agli Ottomani — il comandante si ritira ad Ada Kaleh", "de759b16"], "d": ["All'apertura della campagna del 1738 il comandante di Vidin, Hacı Mehmed Pascià, attaccò il bastione di Erzsébet sul Danubio. L'8 maggio nel pomeriggio un reparto di 4-5 mila sipahi marciò dalla riva sinistra del Danubio su Orșova e attaccò la palanca di Orșova; il comandante austriaco, con un centinaio di perdite, si ritirò a Nuova Orșova, cioè alla fortezza insulare di Ada Kaleh. Dopo gli scontri di Mehadia in luglio, anche Ada Kaleh passò in mano ottomana nell'agosto 1738; il Trattato di Belgrado del 1739 riconobbe la situazione.", "70ee9650"]},
"OLAYLAR_SERHAT:1428-01-01:0":{"b": ["Murad II prende Golubac, Niš e Šehirköy tornano agli Ottomani", "54af926a"], "d": ["Dopo la morte senza eredi del despota serbo Stefan Lazarević (1427), Murad II, adducendo di essere il legittimo erede della Serbia in base al matrimonio di Bayezid il Fulmine con una principessa serba, si mosse e prese Golubac (1428). Nello stesso anno, dopo la morte di Lazarević, gli Ottomani ripresero anche la fortezza di Šehirköy (Pirot) — la città era stata presa nel 1412 da Stefan e difesa contro Mûsâ Çelebi. Secondo la voce TDV nis, gli Ottomani ripresero nello stesso anno (831/1428) anche Niš. Così la linea che collega le valli della Morava Grande e della Nišava entrò sotto controllo ottomano.", "01c87afb"]},
"OLAYLAR_SERHAT:1443-01-01:0":{"b": ["L'esercito crociato prende Šehirköy — il ramo della Nišava della 'Lunga Campagna'", "fdf6140c"], "d": ["L'esercito crociato guidato dal re Vladislao e dal despota serbo Đurađ Branković prese Šehirköy nel 1443. Nel proseguimento della stessa campagna le forze ottomane sarebbero state sconfitte a novembre al passo di Zlatica (İzladi). Šehirköy fu restituita ai Serbi da Murad II dopo il Trattato di Seghedino (1444), ma passò agli Ottomani nel 1456, dopo la morte di Đurađ Branković.", "f56645a4"]},
"OLAYLAR_SERHAT:1458-01-01:0":{"b": ["Stabilito il dominio ottomano definitivo nella regione di Golubac", "9715382a"], "d": ["Golubac, lasciata a Branković al termine dell'accordo del 1444 con i delegati ungheresi, tornò sotto il dominio turco negli anni seguenti alla vittoria di Varna. Questa seconda conquista della città non è documentata da un resoconto di guerra, ma da una scrittura fiscale: i registri di timar di alcuni villaggi dipendenti da Golubac sono datati alla fine del 1453/inizio del 1454; ma questa è solo una testimonianza di villaggi — nel 1454 le forze ottomane furono sconfitte nei dintorni di Golubac e nel 1455 Golubac fu lasciata a Branković come confine. Secondo il TDV, il dominio ottomano definitivo nella regione fu stabilito nel 1458.", "2b6aba24"]},
"OLAYLAR_SESSIZBORC0919:1349-01-01:0":{"b": ["Fondazione del Despotato di Morea — Manuele Cantacuzeno a Mistrà", "87660b82"], "d": ["L'imperatore bizantino Giovanni Cantacuzeno diede al figlio Manuele una circoscrizione amministrativa separata in Morea; così nacque il Despotato di Morea con centro a Mistrà. Manuele governò fino al 1380; in questo periodo la cultura e l'arte bizantine fiorirono soprattutto a Mistrà. Il despotato durò fino alla conquista del Conquistatore nel 1460.", "f5596d5e"]},
"OLAYLAR_SESSIZBORC0919:1430-01-01:0":{"b": ["Il despota Costantino prende Patrasso ai Franchi", "cb0dd18c"], "d": ["Costantino, despota di Morea (nel 1449 ultimo imperatore bizantino), riprese Patrasso ai Latini; così anche questo importante porto nel nord-ovest della penisola fu annesso al despotato. Patrasso entrò sotto il dominio ottomano nel 1458, nella campagna di Morea del Conquistatore.", "98b8dff0"]},
"OLAYLAR_SESSIZBORC0919:1448-01-01:0":{"b": ["Stjepan Vukčić Kosača 'Duca di San Sava' — nascita dell'Erzegovina", "cc67061f"], "d": ["Stjepan Vukčić Kosača, che aveva riunito Hum e Travunia in un unico principato, si ribellò al re di Bosnia e si proclamò 'herceg (duca) di San Sava'; il titolo gli fu conferito nel 1448 dall'imperatore Federico III. Il nome Herzegovina ('terra dell'herceg') deriva da questo titolo. L'Erzegovina passò a pezzi agli Ottomani dal 1466, divenne sanjak nel 1470; i territori rimanenti furono annessi all'inizio del 1482.", "e6a77d9c"]},
"OLAYLAR_SESSIZBORC0919:1525-04-08:0":{"b": ["Pace di Cracovia — lo Stato dell'Ordine Teutonico si trasforma in Ducato di Prussia", "78666ddd"], "d": ["Il gran maestro dei Cavalieri Teutonici, Alberto di Brandeburgo, non avendo trovato aiuto contro la Polonia, firmò la pace di Cracovia. Lo Stato dell'Ordine (Ordensstaat) divenne, sotto la sovranità della Polonia, un ducato ereditario e secolare passato alla dinastia di Brandeburgo. Il centro era Königsberg; Alberto vi fondò nel 1544 l'Università Albertina. Il ducato si trasformò nel 1701 in Regno di Prussia.", "d38ad9a3"]},
"OLAYLAR_SESSIZBORC0919:1918-11-12:0":{"b": ["Proclamazione della Repubblica d'Austria — fine della monarchia asburgica", "c84f316c"], "d": ["Il giorno dopo che l'imperatore Carlo I, l'11 novembre, si fu ritirato dagli affari di Stato, l'Assemblea Nazionale Provvisoria approvò la legge sulla forma dello Stato e del governo e fu proclamata la repubblica. All'Austria asburgica subentrò la Prima Repubblica con centro a Vienna. Con questa proclamazione Vienna, Linz, Salisburgo, Innsbruck, Klagenfurt, Bregenz e le altre città germano-austriache divennero territorio della Repubblica d'Austria (Deutschösterreich).", "2dcc1399"]}
});
